entries.command:
$u=Get-ADUser 'lab-canary' -Properties Description
$old=$u.Description
try {
  Set-ADUser $u -Description 'assessment-canary-47119'
  Get-ADUser $u -Properties Description | Select-Object SamAccountName,Description
} finally {
  if ($null -eq $old) { Set-ADUser $u -Clear Description }
  else { Set-ADUser $u -Description $old }
}
